function demoMain(idx,label){
  var steps=[["kernel","bzImage 8.2MB"],["bootloader","grub.cfg written"],["rootfs","squashfs 120MB"]];
  var s=steps[idx%steps.length];
  return "["+label+"] OS build step '"+s[0]+"': "+s[1]+" (qemu boot OK)";
}

